        "quote": "先尽力挂神经内科"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00031",
        "explanation": "Frames headache in vascular-risk context rather than accepting simple neuralgia.",
        "quote": "不能轻易地归为“神经痛”"
      }
    ],
    "continuity_memory_focus": [
      {
        "event_id": "lite_evt_00599",
